// Start Fixed-Timestep 60Hz Loop
let last = performance.now();
let acc = 0;
const dt = 1 / 60;
const frame = (now) => {
  const elapsed = Math.min(0.1, (now - last) / 1000);
  last = now;
  acc += elapsed;
  while (acc >= dt) {
    this.update(dt, now / 1000);
    acc -= dt;
  }
  this.render(now / 1000);
  requestAnimationFrame(frame);
};
requestAnimationFrame(frame);

